int suma(int n) {
  if (n == 0) {
    return 0;
  }
  return n + suma(n - 1);
}

int factorial(int n) {
  if (n == 0) {
    return 1;
  }
  return n * factorial(n - 1);
}

int potencia(int base, int exp) {
  if (exp == 0) {
    return 1;
  }
  return base * potencia(base, exp - 1);
}

int digitos(int n) {
  if (n < 10) {
    return 1;
  }
  return 1 + digitos(n / 10);
}

int sumaDigitos(int n) {
  if (n == 0) {
    return 0;
  }
  return n % 10 + sumaDigitos(n / 10);
}

